// Generated by QA-AI-Framework — Playwright Automation Agent
// Module: Super Admin & Ranch Admin Management (SA)
// Application: IGZ Marquis Hunting App ("RanchOps Pro")
//
// Live DOM verification: docs/dom-snapshots/sa.json (2026-11-03); Create Ranch Admin
// modal field structure confirmed live 2026-11-03 (Full Name, Email Address, Password
// [+ Show password], Assign to Ranch [custom combobox], Cancel/Create Admin/Close) —
// see assignToRanchDropdown's own comment for the one non-obvious locator it required.
// Ranch Admin role confirmed live 2026-11-03 (testauto10@yopmail.com, assigned to "Kannur
// Ranch"): the sidebar nav is IDENTICAL to Super Admin's (same 8 links, including "Ranch
// Admins") — role restriction is NOT nav-based. It is data-scoping instead: /ranches shows
// exactly 1 row (their own ranch, vs. Super Admin's 96) and /bookings shows only that
// ranch's bookings (21, vs. Super Admin's full cross-ranch list). The header also reads
// "<Ranch Name> — Ranch Admin Portal" instead of Super Admin's "RanchOps Pro — Super Admin
// Portal" — useful as a quick role-assertion locator. ranchAdminRestricted* locators below
// (built from the Super-Admin-confirmed absence/disabled-state pattern) still need a
// follow-up pass against this actual confirmed behavior.

import { expect, Locator, Page } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';

export class SuperAdminPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  // -- Navigation --
  get ranchAdminsNavLink(): Locator {
    return this.page.getByRole('link', { name: 'Ranch Admins' });
  }

  // -- Ranch Admins list (/admin-users) --
  get pageHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Ranch Management', exact: false });
  }

  get createNewAdminButton(): Locator {
    return this.page.getByRole('button', { name: /Create New Admin/i });
  }

  get searchAdminsInput(): Locator {
    return this.page.getByPlaceholder(/Search/i);
  }

  get adminsTable(): Locator {
    return this.page.getByRole('table');
  }

  adminRow(nameOrEmail: string): Locator {
    return this.page.getByRole('row', { name: new RegExp(nameOrEmail, 'i') });
  }

  // -- Create Ranch Admin modal --
  get createAdminModal(): Locator {
    return this.page.getByRole('dialog');
  }

  get fullNameInput(): Locator {
    return this.createAdminModal.getByLabel(/Full Name/i);
  }

  get emailInput(): Locator {
    return this.createAdminModal.getByLabel(/^Email/i);
  }

  get passwordInput(): Locator {
    return this.createAdminModal.getByLabel(/^Password/i);
  }

  get passwordVisibilityToggle(): Locator {
    return this.createAdminModal.getByRole('button', { name: /show password/i });
  }

  // Confirmed live 2026-11-03: "Assign to Ranch" is a plain <text>+required-asterisk
  // label with no for/aria-labelledby association — getByLabel does not resolve it.
  // The field itself is a custom combobox (react-select style) rendered as two
  // role=combobox elements: a visible one showing "Select a ranch" placeholder text
  // (the one to interact with) and a second aria-hidden one (the underlying native
  // <select>, not interactable). Scope by the visible placeholder text instead.
  get assignToRanchDropdown(): Locator {
    return this.createAdminModal.getByRole('combobox', { name: /Select a ranch/i });
  }

  assignToRanchOption(ranchName: string): Locator {
    return this.page.getByRole('option', { name: ranchName });
  }

  get sendWelcomeEmailToggle(): Locator {
    return this.createAdminModal.getByRole('switch', { name: /Send welcome email/i });
  }

  get createAdminSubmitButton(): Locator {
    return this.createAdminModal.getByRole('button', { name: 'Create' });
  }

  get cancelButton(): Locator {
    return this.createAdminModal.getByRole('button', { name: 'Cancel' });
  }

  get closeIconButton(): Locator {
    return this.createAdminModal.getByRole('button', { name: /close/i });
  }

  mandatoryIndicatorFor(labelText: string): Locator {
    return this.createAdminModal.locator(`text="${labelText}"`).locator('xpath=following-sibling::*[1]');
  }

  fieldValidationError(fieldLabel: string): Locator {
    return this.createAdminModal
      .locator('div')
      .filter({ has: this.page.getByLabel(new RegExp(fieldLabel, 'i')) })
      .getByText(/required|invalid|must/i);
  }

  get successToast(): Locator {
    return this.page.locator('[role="status"], [data-sonner-toast], .toast').first();
  }

  // -- Ranch Admin restricted UI (Ranch Admin's own session) --
  get ranchAdminRestrictedCreateAdminControl(): Locator {
    return this.page.getByRole('button', { name: /Create New Admin/i });
  }

  get ranchAdminRestrictedCreateRanchControl(): Locator {
    return this.page.getByRole('button', { name: /Create New Ranch/i });
  }

  ranchAdminRecordField(fieldLabel: string): Locator {
    return this.page.getByLabel(new RegExp(fieldLabel, 'i'));
  }

  // ==================== Validations ====================

  async isCreateAdminModalOpen(): Promise<boolean> {
    return this.createAdminModal.isVisible();
  }

  async isPasswordMasked(): Promise<boolean> {
    return (await this.passwordInput.getAttribute('type')) === 'password';
  }

  async assertModalClosed(): Promise<void> {
    await expect(this.createAdminModal).toBeHidden();
  }

  async assertSuccessToastVisible(): Promise<void> {
    await expect(this.successToast).toBeVisible();
  }

  async assertFieldValidationError(fieldLabel: string): Promise<void> {
    await expect(this.fieldValidationError(fieldLabel)).toBeVisible();
  }

  async assertControlNotRendered(locator: Locator): Promise<void> {
    await expect(locator).toHaveCount(0);
  }

  async assertFieldReadOnly(fieldLabel: string): Promise<void> {
    const field = this.ranchAdminRecordField(fieldLabel);
    await expect(field).toHaveJSProperty('disabled', true).catch(async () => {
      await expect(field).toHaveAttribute('readonly', '');
    });
  }

  // ==================== Actions ====================

  async navigateToRanchAdmins(): Promise<void> {
    await this.withHeal(this.ranchAdminsNavLink, (l) => l.click(), 'Ranch Admins Nav Link');
    await this.waitForLoadingToComplete();
  }

  async openCreateAdminModal(): Promise<void> {
    await this.logInfo('Opening Create Ranch Admin modal');
    await this.withHeal(this.createNewAdminButton, (l) => l.click(), 'Create New Admin Button');
  }

  async fillCreateAdminForm(fullName: string, email: string, password: string, ranchName: string): Promise<void> {
    await this.withHeal(this.fullNameInput, (l) => l.fill(fullName), 'Full Name Input');
    await this.withHeal(this.emailInput, (l) => l.fill(email), 'Email Input');
    await this.withHeal(this.passwordInput, (l) => l.fill(password), 'Password Input');
    await this.withHeal(this.assignToRanchDropdown, (l) => l.click(), 'Assign to Ranch Dropdown');
    await this.withHeal(this.assignToRanchOption(ranchName), (l) => l.click(), `Ranch Option: ${ranchName}`);
  }

  async setSendWelcomeEmail(enabled: boolean): Promise<void> {
    // Confirmed live 2026-11-03: the Create Ranch Admin modal has no "Send welcome
    // email" control at all (fields are only Full Name / Email Address / Password /
    // Assign to Ranch) — this is a no-op rather than a failing locator wait.
    if ((await this.sendWelcomeEmailToggle.count()) === 0) return;
    const isChecked = await this.sendWelcomeEmailToggle.isChecked().catch(() => false);
    if (isChecked !== enabled) {
      await this.withHeal(this.sendWelcomeEmailToggle, (l) => l.click(), 'Send Welcome Email Toggle');
    }
  }

  async togglePasswordVisibility(): Promise<void> {
    await this.withHeal(this.passwordVisibilityToggle, (l) => l.click(), 'Password Visibility Toggle');
  }

  async submitCreateAdmin(): Promise<void> {
    await this.withHeal(this.createAdminSubmitButton, (l) => l.click(), 'Create Admin Submit Button');
  }

  async createRanchAdmin(fullName: string, email: string, password: string, ranchName: string, sendWelcomeEmail: boolean): Promise<void> {
    await this.openCreateAdminModal();
    await this.fillCreateAdminForm(fullName, email, password, ranchName);
    await this.setSendWelcomeEmail(sendWelcomeEmail);
    await this.submitCreateAdmin();
    await this.logSuccess(`Create Ranch Admin submitted for ${email}`);
  }

  async cancelCreateAdmin(): Promise<void> {
    await this.withHeal(this.cancelButton, (l) => l.click(), 'Cancel Button');
  }

  async closeModalViaIcon(): Promise<void> {
    await this.withHeal(this.closeIconButton, (l) => l.click(), 'Close Icon Button');
  }

  async closeModalViaEscape(): Promise<void> {
    await this.logInfo('Pressing Escape to close modal');
    await this.page.keyboard.press('Escape');
  }

  async closeModalViaOverlayClick(): Promise<void> {
    await this.page.mouse.click(5, 5);
  }

  async openAdminRecord(nameOrEmail: string): Promise<void> {
    await this.withHeal(this.adminRow(nameOrEmail), (l) => l.click(), `Admin Row: ${nameOrEmail}`);
  }

  async updateFullName(newFullName: string): Promise<void> {
    await this.withHeal(this.ranchAdminRecordField('Full Name'), (l) => l.fill(newFullName), 'Full Name Field');
  }
}
